/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        ListNode p = l1;
        ListNode q = l2;
        ListNode prev = null;

        int carry = 0;

        while (p != null || q != null) {

            int val1 = (p != null) ? p.val : 0;
            int val2 = (q != null) ? q.val : 0;

            int sum = val1 + val2 + carry;

            int value = sum % 10;
            carry = sum / 10;
            
            if (p != null) {
                p.val = value;
                prev = p;
                p = p.next;
            } else {
                // l1 ended → attach new node
                prev.next = new ListNode(value);
                prev = prev.next;
            }

            if (q != null) q = q.next;
        }

        // leftover carry
        if (carry != 0) {
            prev.next = new ListNode(carry);
        }

        return l1;
    }
}

class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int m = nums2.length;
        int[] mergeArray = new int[n+m];
        int i = 0;
        int j = 0;
        for(int k = 0 ; k < (n+m) ; k++){
            if (i == n) {
                mergeArray[k] = nums2[j++];
            } else if (j == m) {
                mergeArray[k] = nums1[i++];
            } else if (nums1[i] <= nums2[j]) {
                mergeArray[k] = nums1[i++];
            } else {
                mergeArray[k] = nums2[j++];
            }             
        }
        int mid = (n+m)/2;
        if((n+m)%2==0){
            return (double)(mergeArray[mid-1]+mergeArray[mid])/2;
        }
        return mergeArray[mid];
    }
}

