            while( currentSum >= target){
                if(currentSum == target){
                    minOp = Math.min(minOp , (nums.length - (right-left+1)) );
                }
                currentSum -= nums[left];
                left++;
            } 
        }

        if(minOp == Integer.MAX_VALUE){
            return -1;
        }
        return minOp;
    }
}

class Solution {
    public int[] getConcatenation(int[] nums) {
        int ans[] = new int [nums.length+nums.length];
        for(int i = 0 ; i < nums.length ; i++){
            ans[i] = nums[i];
            ans[i+nums.length] = nums[i];
        }
        return ans;
    }
}

class Solution {
    public int[] findMissingAndRepeatedValues(int[][] grid) {
        int count[] = new int [grid.length*grid.length];
        for(int i = 0; i<grid.length ; i++){
            for(int j = 0; j<grid.length ; j++){
                count[grid[i][j]-1] = count[grid[i][j]-1] + 1;
            }
        }
        int A = 0 , B = 0;
        for(int i = 0 ; i < count.length ; i++){
            if(count[i] == 2){
                A = i+1;
            }
            if(count[i] == 0){
                B = i+1;
            }
        }   
       
        return new int[]{A,B};
        
    }
}

class Solution {
    
    public int reverseDegree(String s) {
        int sum = 0;
        for (int i = 0; i < s.length(); i++) {
            int reversed_Index = 'z' - s.charAt(i) + 1;
            sum += (i + 1)*reversed_Index ;
        }
        return sum;
    }
    
}
